class ArgumentParser:
    def __init__(self):
        self._arguments = {}
        self._required = set()
        self._types = {}

    def parse_arguments(self, command_string):
        args = command_string.split()[1:]
        for i in range(len(args)):
            arg = args[i]
            if self._is_long_option(arg):
                self._handle_long_option(arg)
            elif self._is_short_option(arg):
                self._handle_short_option(arg, i, args)
        missing_args = self._get_missing_required_args()
        if missing_args:
            return False, missing_args

        return True, None

    def _is_long_option(self, arg):
        return arg.startswith('--')

    def _is_short_option(self, arg):
        return arg.startswith('-')

    def _handle_long_option(self, arg):
        key_value = arg[2:].split('=')
        if len(key_value) == 2:
            self._arguments[key_value[0]] = self._convert_type(key_value[0], key_value[1])
        else:
            self._arguments[key_value[0]] = True

    def _handle_short_option(self, arg, index, args):
        key = arg[1:]
        if self._has_next_value(index, args):
            self._arguments[key] = self._convert_type(key, args[index + 1])
        else:
            self._arguments[key] = True

    def _has_next_value(self, index, args):
        return (index + 1 < len(args)) and (not args[index + 1].startswith('-'))

    def _get_missing_required_args(self):
        return self._required - set(self._arguments.keys())

    def get_argument(self, key):
        return self._arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        self._add_required(arg, required)
        self._types[arg] = arg_type

    def _add_required(self, arg, required):
        if required:
            self._required.add(arg)

    def _convert_type(self, arg, value):
        try:
            return self._types[arg](value)
        except (ValueError, KeyError):
            return value

    @property
    def arguments(self):
        return dict(self._arguments)

    @arguments.setter
    def arguments(self, value):
        self._arguments = dict(value)

    @property
    def required(self):
        return frozenset(self._required)

    @required.setter
    def required(self, value):
        self._required = set(value)

    @property
    def types(self):
        return dict(self._types)

    @types.setter
    def types(self, value):
        self._types = dict(value)

class ArgumentParser:
    DEFAULT_FLAGS = {'--', '-'}
    FLAG_SEPARATOR = '='
    FLAG_PREFIX_LONG = '--'
    FLAG_PREFIX_SHORT = '-'
    OPTION_VALUE_POSITION = 1

    def __init__(self):
        self._arguments = {}
        self._required = set()
        self._types = {}

    def parse_arguments(self, command_string):
        args = self._extract_arguments(command_string)
        for i, arg in self._iter_args_with_values(args):
            if self._is_long_flag(arg):
                self._handle_long_flag(arg)
            elif self._is_short_flag(arg):
                self._handle_short_flag(arg, args, i)

        missing_args = self._get_missing_required_args()
        if missing_args:
            return False, missing_args

        return True, None

    def get_argument(self, key):
        return self._arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        if required:
            self._required.add(arg)
        self._types[arg] = arg_type

    def _extract_arguments(self, command_string):
        return command_string.split()[1:]

    def _iter_args_with_values(self, args):
        for i in range(len(args)):
            yield i, args[i]

    def _is_long_flag(self, arg):
        return arg.startswith(self.FLAG_PREFIX_LONG)

    def _is_short_flag(self, arg):
        return arg.startswith(self.FLAG_PREFIX_SHORT)

    def _handle_long_flag(self, arg):
        key_value = arg[len(self.FLAG_PREFIX_LONG):].split(self.FLAG_SEPARATOR)
        if len(key_value) == 2:
            self._arguments[key_value[0]] = self._convert_type(key_value[0], key_value[1])
        else:
            self._arguments[key_value[0]] = True

    def _handle_short_flag(self, arg, args, index):
        key = arg[len(self.FLAG_PREFIX_SHORT):]
        if self._has_value_following(index, args):
            self._arguments[key] = self._convert_type(key, args[index + 1])
        else:
            self._arguments[key] = True

    def _has_value_following(self, index, args):
        return index + 1 < len(args) and not args[index + 1].startswith('-')

    def _get_missing_required_args(self):
        return self._required - set(self._arguments.keys())

    def _convert_type(self, arg, value):
        return self._safe_convert(arg, value)

    def _safe_convert(self, arg, value):
        try:
            return self._types[arg](value)
        except (ValueError, KeyError):
            return value

import itertools


class ArrangementCalculator:
    FULL_ARRANGEMENT_MULTIPLE = 1

    def __init__(self, datas):
        self._datas = list(datas)

    @staticmethod
    def count(n, m=None):
        if m is None or n == m:
            return ArrangementCalculator.factorial(n)
        return ArrangementCalculator.factorial(n) // ArrangementCalculator.factorial(n - m)

    @staticmethod
    def count_all(n):
        return sum(ArrangementCalculator.count(n, i) for i in range(1, n + 1))

    @property
    def datas(self):
        return list(self._datas)

    @datas.setter
    def datas(self, value):
        self._datas = list(value)

    def select(self, m=None):
        if m is None:
            m = len(self._datas)
        return self._generate_permutations(m)

    def select_all(self):
        return self._generate_all_permutations()

    def _generate_permutations(self, m):
        return [list(permutation) for permutation in itertools.permutations(self._datas, m)]

    def _generate_all_permutations(self):
        return [
            permutation
            for i in range(1, len(self._datas) + 1)
            for permutation in self._generate_permutations(i)
        ]

    @staticmethod
    def factorial(n):
        return ArrangementCalculator._compute_factorial(n)

    @staticmethod
    def _compute_factorial(n):
        return 1 if n <= 1 else n * ArrangementCalculator._compute_factorial(n - 1)

import itertools


class ArrangementCalculator:
    def __init__(self, datas):
        self.datas = datas

    @staticmethod
    def count(n, m=None):
        if m is None or n == m:
            return ArrangementCalculator.factorial(n)
        else:
            return ArrangementCalculator.factorial(n) // ArrangementCalculator.factorial(n - m)

    @staticmethod
    def count_all(n):
        total = 0
        for i in range(1, n + 1):
            total += ArrangementCalculator.count(n, i)
        return total

    def select(self, m=None):
        if m is None:
            m = len(self.datas)
        return [list(permutation) for permutation in itertools.permutations(self.datas, m)]

    def select_all(self):
        return [item for i in range(1, len(self.datas) + 1) for item in self.select(i)]

    @staticmethod
    def factorial(n):
        result = 1
        for i in range(2, n + 1):
            result *= i
