        self._right_brackets = [self.CLOSE_BRACKET, self.CLOSE_CURLY_BRACKET, self.CLOSE_SQUARE_BRACKET]
        self._expr = expr

    @property
    def stack(self):
        return self._stack

    @property
    def left_brackets(self):
        return self._left_brackets

    @property
    def right_brackets(self):
        return self._right_brackets

    @property
    def expr(self):
        return self._expr

    @expr.setter
    def expr(self, value):
        self._expr = value

    def clear_expr(self):
        valid_brackets = set(self.left_brackets + self.right_brackets)
        self._expr = ''.join(c for c in self._expr if c in valid_brackets)

    def _is_matching_pair(self, left_brkt, right_brkt):
        if left_brkt == self.OPEN_BRACKET:
            return right_brkt == self.CLOSE_BRACKET
        if left_brkt == self.OPEN_CURLY_BRACKET:
            return right_brkt == self.CLOSE_CURLY_BRACKET
        if left_brkt == self.OPEN_SQUARE_BRACKET:
            return right_brkt == self.CLOSE_SQUARE_BRACKET
        return False

    def check_balanced_brackets(self):
        self.clear_expr()
        self._stack.clear()
        for brkt in self.expr:
            if brkt in self.left_brackets:
                self._stack.append(brkt)
            else:
                if not self._stack:
                    return False
                current_brkt = self._stack.pop()
                if not self._is_matching_pair(current_brkt, brkt):
                    return False
        return len(self._stack) == 0

class BalancedBrackets:
    LEFT_BRACKETS = ["(", "{", "["]
    RIGHT_BRACKETS = [")", "}", "]"]
    BRACKET_PAIRS = {
        "(": ")",
        "{": "}",
        "[": "]"
    }

    def __init__(self, expr):
        self.stack = []
        self.expr = expr

    def clear_expr(self):
        self.expr = ''.join(c for c in self.expr if c in self.LEFT_BRACKETS or c in self.RIGHT_BRACKETS)

    def check_balanced_brackets(self):
        self.clear_expr()
        for bracket in self.expr:
            if not self.process_bracket(bracket):
                return False
        return not self.is_unbalanced_stack()

    def process_bracket(self, bracket):
        if bracket in self.LEFT_BRACKETS:
            self.stack.append(bracket)
            return True
        else:
            if not self.stack:
                return False
            current_bracket = self.stack.pop()
            return self.are_matching_brackets(current_bracket, bracket)

    def is_unbalanced_stack(self):
        return bool(self.stack)

    def are_matching_brackets(self, opened, closed):
        return self.BRACKET_PAIRS.get(opened) == closed

class BalancedBrackets:
    LEFT_BRACKETS = ["(", "{", "["]
    RIGHT_BRACKETS = [")", "}", "]"]
    LEFT_BRACKET_TO_RIGHT_BRACKET = {"(": ")", "{": "}", "[": "]"}

    def __init__(self, expr):
        self._stack = []
        self._left_brackets = self.LEFT_BRACKETS
        self._right_brackets = self.RIGHT_BRACKETS
        self._expr = expr

    @property
    def stack(self):
        return self._stack

    def clear_expr(self):
        self._expr = ''.join(c for c in self._expr if (c in self._left_brackets or c in self._right_brackets))

    def _is_left_bracket(self, char):
        return char in self._left_brackets

    def _validate_bracket_pair(self, left_bracket, right_bracket):
        return left_bracket != self.LEFT_BRACKET_TO_RIGHT_BRACKET.get(right_bracket)

    def check_balanced_brackets(self):
        self.clear_expr()
        for bracket in self._expr:
            if self._is_left_bracket(bracket):
                self._stack.append(bracket)
            else:
                if not self._stack:
                    return False
                current_bracket = self._stack.pop()
                if self._validate_bracket_pair(current_bracket, bracket):
                    return False
        return not self._stack

class BalancedBrackets:
    LEFT_BRACKETS = ("(", "{", "[")
    RIGHT_BRACKETS = (")", "}", "]")
    BRACKET_PAIRS = {")": "(", "}": "{", "]": "["}

    def __init__(self, expr):
        self._stack = []
        self._left_brackets = list(self.LEFT_BRACKETS)
        self._right_brackets = list(self.RIGHT_BRACKETS)
        self._expr = expr

    @property
    def expr(self):
        return self._expr

    @expr.setter
    def expr(self, value):
        self._expr = value

    @property
    def stack(self):
        return self._stack

    def clear_expr(self):
        self.expr = ''.join(c for c in self.expr if (c in self.left_brackets or c in self.right_brackets))

    def _process_bracket(self, bracket):
        if bracket in self.left_brackets:
            self.stack.append(bracket)
        else:
            self._validate_bracket_match(bracket)

    def _validate_bracket_match(self, closing_bracket):
        if not self.stack:
            raise ValueError("Unmatched closing bracket found")
        current_brkt = self.stack.pop()
        expected_opening = self.BRACKET_PAIRS[closing_bracket]
        if current_brkt != expected_opening:
            return False
        return True

    @property
    def left_brackets(self):
        return self._left_brackets

    @left_brackets.setter
    def left_brackets(self, value):
        self._left_brackets = value

    @property
    def right_brackets(self):
        return self._right_brackets

    @right_brackets.setter
    def right_brackets(self, value):
        self._right_brackets = value

    def check_balanced_brackets(self):
        self.clear_expr()
        for Brkt in self.expr:
            self._process_bracket(Brkt)
        return not self.stack

