        self._deck = []
        self._player_hand = []
        self._dealer_hand = []
        self._shuffle_and_set_deck()

    def _shuffle_and_set_deck(self):
        deck = self._create_deck()
        random.shuffle(deck)
        self._deck = deck

    def _create_deck(self):
        deck = []
        for suit in self.SUITS:
            for rank in self.RANKS:
                deck.append(rank + suit)
        return deck

    @property
    def deck(self):
        return self._deck

    @property
    def player_hand(self):
        return list(self._player_hand)

    @player_hand.setter
    def player_hand(self, hand):
