    @property
    def dealer_hand(self):
        return list(self._dealer_hand)

    @dealer_hand.setter
    def dealer_hand(self, hand):
        self._dealer_hand = list(hand)

    def calculate_hand_value(self, hand):
        return self._calculate_hand_value(hand)

    def _calculate_hand_value(self, hand):
        value = 0
        num_aces = 0
        for card in hand:
            value_with_aces = self._get_card_value(card)
            value += value_with_aces
            if self._is_ace(card):
                num_aces += 1
                value += 10
        while value > self.MAX_VALUE and num_aces > 0:
            value -= 10
            num_aces -= 1
        return value

    def _get_card_value(self, card):
        rank = self._get_rank(card)
        if self._is_face_card(rank):
            return self.FACE_CARD_VALUE
        return self._get_numeric_rank_value(rank)

    def _get_rank(self, card):
        return card[:-1]

    def _is_face_card(self, rank):
        return rank in ['J', 'Q', 'K']

