        if _is_base_case(n, m):
            return 1
        return _compute_combination(n, m)

    @staticmethod
    def _is_base_case(n: int, m: int) -> bool:
        return m == 0 or n == m

    @staticmethod
    def _compute_combination(n: int, m: int) -> int:
        return math.factorial(n) // (math.factorial(n - m) * math.factorial(m))

    @staticmethod
    def count_all(n: int) -> int:
        if _is_invalid_n(n):
            return False
        return _compute_all_combinations(n)

    @staticmethod
    def _is_invalid_n(n: int) -> bool:
        return n < 0 or n > CombinationCalculator.MAX_N

    @staticmethod
    def _compute_all_combinations(n: int) -> int:
        if n == CombinationCalculator.MAX_N:
            return CombinationCalculator.INF_VALUE
        return (1 << n) - 1

    def select(self, m: int) -> List[List[str]]:
