    def _place_mark(self, row, col):
        self._board[row][col] = self._current_player

    def _switch_player(self):
        self._current_player = PlayerState.O if self._current_player == PlayerState.X else PlayerState.X

    def check_winner(self):
        return self._find_winner_in_board()

    def _find_winner_in_board(self):
        for row in range(self._board_size):
            for col in range(self._board_size):
                if self._board[row][col] != PlayerState.EMPTY:
                    winner = self._check_directions_at(row, col)
                    if winner is not None:
                        return winner
        return None

    def _check_directions_at(self, row, col):
        for direction in self.DIRECTIONS:
            if self._check_five_in_a_row(row, col, direction):
                return self._board[row][col].value
        return None

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        count = self._count_consecutive_marks(row, col, dx, dy)
        return count >= self.FIVE_IN_A_ROW

    def _count_consecutive_marks(self, row, col, dx, dy):
        symbol = self._board[row][col]
        count = 1
        for i in range(1, self.FIVE_IN_A_ROW):
            new_row = row + dx * i
            new_col = col + dy * i
            if not self._is_within_bounds(new_row, new_col):
                return count
            if self._board[new_row][new_col] != symbol:
                return count
            count += 1
        return count

    def _is_within_bounds(self, row, col):
        return 0 <= row < self._board_size and 0 <= col < self._board_size

class GomokuGame:
    EMPTY_CELL = ' '
    PLAYER_X = 'X'
    PLAYER_O = 'O'
    WIN_SIZE = 5
    DIRECTIONS = [(0, 1), (1, 0), (1, 1), (1, -1)]

    def __init__(self, board_size):
        self._board_size = board_size
        self._board = [[self.EMPTY_CELL for _ in range(board_size)] for _ in range(board_size)]
        self._current_player = self.PLAYER_X

    @property
    def board_size(self):
        return self._board_size

    @property
    def board(self):
        return self._board

    @property
    def current_player(self):
        return self._current_player

    def make_move(self, row, col):
        if self._board[row][col] == self.EMPTY_CELL:
            self._board[row][col] = self._current_player
            self._current_player = self._get_opposite_player(self._current_player)
            return True
        return False

    def _get_opposite_player(self, player):
        return self.PLAYER_O if player == self.PLAYER_X else self.PLAYER_X

    def check_winner(self):
        for row in range(self._board_size):
            for col in range(self._board_size):
                if self._board[row][col] != self.EMPTY_CELL:
                    for direction in self.DIRECTIONS:
                        if self._check_five_in_a_row(row, col, direction):
                            return self._board[row][col]
        return None

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        symbol = self._board[row][col]
        for i in range(1, self.WIN_SIZE):
            new_row = row + dx * i
            new_col = col + dy * i
            if not (0 <= new_row < self._board_size and 0 <= new_col < self._board_size):
                return False
            if self._board[new_row][new_col] != symbol:
                return False
        return True

class Hotel:
    def __init__(self, name, rooms):
        self.name = name
        self._available_rooms = rooms
        self._booked_rooms = {}

    @property
    def available_rooms(self):
        return self._available_rooms

    @property
    def booked_rooms(self):
        return self._booked_rooms

    def book_room(self, room_type, room_number, name):
        if room_type not in self.available_rooms:
            return False

        if room_number <= self.available_rooms[room_type]:
            self._book_room(room_type, room_number, name)
            return "Success!"
        elif self.available_rooms[room_type] != 0:
            return self.available_rooms[room_type]
        else:
            return False

    def _book_room(self, room_type, room_number, name):
        if room_type not in self.booked_rooms:
            self._booked_rooms[room_type] = {}
        self._booked_rooms[room_type][name] = room_number
        self._available_rooms[room_type] -= room_number

    def check_in(self, room_type, room_number, name):
        if room_type not in self.booked_rooms:
            return False
        if name in self.booked_rooms[room_type]:
            self._process_check_in(room_type, room_number, name)

    def _process_check_in(self, room_type, room_number, name):
        booked_room_number = self.booked_rooms[room_type][name]
        if room_number > booked_room_number:
            return False
        elif room_number == booked_room_number:
            self._booked_rooms[room_type].pop(name)
        else:
            self._booked_rooms[room_type][name] = booked_room_number - room_number

    def check_out(self, room_type, room_number):
        self._add_available_rooms(room_type, room_number)

    def _add_available_rooms(self, room_type, room_number):
        if room_type in self._available_rooms:
            self._available_rooms[room_type] += room_number
        else:
            self._available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        return self._available_rooms[room_type]

