        self.employees[employee_id] = {
            'name': name,
            'position': position,
            'department': department,
            'salary': salary
        }
        return True

    def remove_employee(self, employee_id):
        if not self._employee_exists(employee_id):
            return False
        del self.employees[employee_id]
        return True

    def update_employee(self, employee_id: int, employee_info: dict):
        employee = self.get_employee(employee_id)
        if employee is self.NOT_FOUND:
            return False
        if not self._is_valid_employee_update(employee_info):
            return False
        self._apply_employee_update(employee, employee_info)
        return True

    def get_employee(self, employee_id):
        return self._get_employee_by_id(employee_id)

    def list_employees(self):
        return self._build_employee_data()

    def _employee_exists(self, employee_id):
        return employee_id in self.employees

    def _is_valid_employee_update(self, employee_info):
        return all(key in self.VALID_EMPLOYEE_FIELDS for key in employee_info)

    def _apply_employee_update(self, employee, employee_info):
        for key, value in employee_info.items():
            employee[key] = value

    def _get_employee_by_id(self, employee_id):
        return self.employees.get(employee_id, self.NOT_FOUND)

    def _build_employee_data(self):
        employee_data = {}
        for employee_id, employee_info in self.employees.items():
            employee_data[employee_id] = self._build_employee_details(employee_id, employee_info)
        return employee_data

    def _build_employee_details(self, employee_id, employee_info):
        details = {'employee_ID': employee_id}
        details.update(employee_info)
        return details

import re
import string
import gensim
from bs4 import BeautifulSoup


class HtmlUtil:

    def __init__(self):
        self.SPACE_MARK = '-SPACE-'
        self.JSON_MARK = '-JSON-'
        self.MARKUP_LANGUAGE_MARK = '-MARKUP_LANGUAGE-'
        self.URL_MARK = '-URL-'
        self.NUMBER_MARK = '-NUMBER-'
        self.TRACE_MARK = '-TRACE-'
        self.COMMAND_MARK = '-COMMAND-'
        self.COMMENT_MARK = '-COMMENT-'
        self.CODE_MARK = '-CODE-'

    @staticmethod
    def __format_line_feed(text):
        return re.sub(re.compile(r'\n+'), '\n', text)

    def _is_empty_text(self, text):
        return text is None or len(text) == 0

    def _has_punctuation_ending(self, text):
        return text[-1] in string.punctuation

    def _add_period_if_no_punctuation_ending(self, text):
        if self._has_punctuation_ending(text):
            return text
        return text + '.'

    def _process_list_items(self, ul_ol_item):
        li_group = ul_ol_item.find_all('li')
        for li_item in li_group:
            li_item_text = li_item.get_text().strip()
            if len(li_item_text) == 0:
                continue
            if li_item_text[-1] in string.punctuation:
                li_item.string = '[{0}]{1}'.format('-', li_item_text)
                continue
            li_item.string = '[{0}]{1}.'.format('-', li_item_text)

    def _process_paragraph(self, p_item):
        p_item_text = p_item.get_text().strip()
        if p_item_text:
            if p_item_text[-1] in string.punctuation:
                p_item.string = p_item_text
                return
            next_sibling = p_item.find_next_sibling()
            if next_sibling and self.CODE_MARK in next_sibling.get_text():
                p_item.string = p_item_text + ':'
                return
            p_item.string = p_item_text + '.'

    def format_line_html_text(self, html_text):
        if self._is_empty_text(html_text):
            return ''
        soup = BeautifulSoup(html_text, 'lxml')

        code_tag = soup.find_all(name=['pre', 'blockquote'])
        for tag in code_tag:
            tag.string = self.CODE_MARK

        ul_ol_group = soup.find_all(name=['ul', 'ol'])
        for ul_ol_item in ul_ol_group:
            self._process_list_items(ul_ol_item)

        p_group = soup.find_all(name=['p'])
        for p_item in p_group:
            self._process_paragraph(p_item)

        clean_text = gensim.utils.decode_htmlentities(soup.get_text())
        return self.__format_line_feed(clean_text)

    def _extract_code_blocks(self, html_text, text_with_code_tag):
        code_index_start = 0
        soup = BeautifulSoup(html_text, 'lxml')
        code_tag = soup.find_all(name=['pre', 'blockquote'])
        code_count = text_with_code_tag.count(self.CODE_MARK)
        code_list = []
        for code_index in range(code_index_start, code_index_start + code_count):
            code = code_tag[code_index].get_text()
            if code:
                code_list.append(code)
        return code_list

    def extract_code_from_html_text(self, html_text):
        text_with_code_tag = self.format_line_html_text(html_text)

        if self.CODE_MARK not in text_with_code_tag:
            return []

        return self._extract_code_blocks(html_text, text_with_code_tag)

