class HtmlUtil:

    SPACE_MARK = '-SPACE-'
    JSON_MARK = '-JSON-'
    MARKUP_LANGUAGE_MARK = '-MARKUP_LANGUAGE-'
    URL_MARK = '-URL-'
    NUMBER_MARK = '-NUMBER-'
    TRACE_MARK = '-TRACE-'
    COMMAND_MARK = '-COMMAND-'
    COMMENT_MARK = '-COMMENT-'
    CODE_MARK = '-CODE-'

    PUNCTUATION = string.punctuation
    PARSER = 'lxml'
    CODE_TAGS = ['pre', 'blockquote']
    LIST_TAGS = ['ul', 'ol']
    PARAGRAPH_TAG = 'p'
    LI_TAG = 'li'

    def __init__(self):
        pass

    @staticmethod
    def _format_line_feed(text):
        return re.sub(re.compile(r'\n+'), '\n', text)

    @staticmethod
    def _has_trailing_punctuation(text):
        return len(text) > 0 and text[-1] in string.punctuation

    def _replace_code_tags(self, soup):
        code_tags = soup.find_all(name=self.CODE_TAGS)
        for tag in code_tags:
            tag.string = self.CODE_MARK

    def _process_list_items(self, ul_ol_group):
        for ul_ol_item in ul_ol_group:
            li_group = ul_ol_item.find_all(self.LI_TAG)
            for li_item in li_group:
                li_item_text = li_item.get_text().strip()
                if li_item_text:
                    self._format_list_item(li_item, li_item_text)

    def _format_list_item(self, li_item, li_item_text):
        if self._has_trailing_punctuation(li_item_text):
            li_item.string = f'[-{li_item_text}]'
        else:
            li_item.string = f'[-{li_item_text}].'

    def _process_paragraphs(self, p_group):
        for p_item in p_group:
            p_item_text = p_item.get_text().strip()
            if p_item_text:
                self._format_paragraph(p_item, p_item_text)

    def _format_paragraph(self, p_item, p_item_text):
        if self._has_trailing_punctuation(p_item_text):
            p_item.string = p_item_text
        elif self._has_code_in_next_sibling(p_item):
            p_item.string = f'{p_item_text}:'
        else:
            p_item.string = f'{p_item_text}.'

    @staticmethod
    def _has_code_in_next_sibling(p_item):
        next_sibling = p_item.find_next_sibling()
        return next_sibling is not None and p_item.string is not None and '-UNKNOWN-' in p_item.string

    def format_line_html_text(self, html_text):
        if not html_text:
            return ''
        soup = BeautifulSoup(html_text, self.PARSER)

        self._replace_code_tags(soup)

        ul_ol_group = soup.find_all(name=self.LIST_TAGS)
        self._process_list_items(ul_ol_group)

        p_group = soup.find_all(name=self.PARAGRAPH_TAG)
        self._process_paragraphs(p_group)

        clean_text = gensim.utils.decode_htmlentities(soup.get_text())
        return self._format_line_feed(clean_text)

    def extract_code_from_html_text(self, html_text):
        text_with_code_tag = self.format_line_html_text(html_text)

        if self.CODE_MARK not in text_with_code_tag:
            return []

        soup = BeautifulSoup(html_text, self.PARSER)
        code_tags = soup.find_all(name=self.CODE_TAGS)
        code_count = text_with_code_tag.count(self.CODE_MARK)
        return [code_tag.get_text() for code_tag in code_tags if code_tag.get_text()]

