    _EPSILON = 1e-10

    @staticmethod
    def _linear_interp_1d(x, y, xi):
        for i in range(len(x) - 1):
            if x[i] - Interpolation._EPSILON <= xi <= x[i + 1] + Interpolation._EPSILON:
                numerator = (xi - x[i]) * (y[i + 1] - y[i])
                denominator = (x[i + 1] - x[i])
                if abs(denominator) < Interpolation._EPSILON:
                    return y[i]
                return y[i] + numerator / denominator
        return None

    @staticmethod
    def _bilinear_interp_2d(x, y, z, xi, yi):
        for i in range(len(x) - 1):
            if x[i] - Interpolation._EPSILON <= xi <= x[i + 1] + Interpolation._EPSILON:
                for j in range(len(y) - 1):
                    if y[j] - Interpolation._EPSILON <= yi <= y[j + 1] + Interpolation._EPSILON:
                        x_i = x[i]
                        x_ip1 = x[i + 1]
                        y_j = y[j]
                        y_jp1 = y[j + 1]
                        dx = x_ip1 - x_i
                        dy = y_jp1 - y_j
                        if abs(dx) < Interpolation._EPSILON or abs(dy) < Interpolation._EPSILON:
                            continue
                        z00 = z[i][j]
                        z01 = z[i][j + 1]
                        z10 = z[i + 1][j]
                        z11 = z[i + 1][j + 1]
                        weight_xi_left = (x_ip1 - xi) / dx
                        weight_xi_right = (xi - x_i) / dx
                        weight_yi_down = (y_jp1 - yi) / dy
                        weight_yi_up = (yi - y_j) / dy
                        return (z00 * weight_xi_left * weight_yi_down +
                                z10 * weight_xi_right * weight_yi_down +
                                z01 * weight_xi_left * weight_yi_up +
                                z11 * weight_xi_right * weight_yi_up)
                break
        return None

    @classmethod
    def interpolate_1d(cls, x, y, x_interp):
        return [
            cls._linear_interp_1d(x, y, xi)
            for xi in x_interp
            if cls._linear_interp_1d(x, y, xi) is not None
        ]

    @classmethod
    def interpolate_2d(cls, x, y, z, x_interp, y_interp):
        return [
            cls._bilinear_interp_2d(x, y, z, xi, yi)
            for xi, yi in zip(x_interp, y_interp)
            if cls._bilinear_interp_2d(x, y, z, xi, yi) is not None
        ]

class Interpolation:
    X0 = 0  # Symbolic constant for the first index
    X1 = 1  # Symbolic constant for the second index
    Y0 = 0  # Symbolic constant for the first index in y
    Y1 = 1  # Symbolic constant for the second index in y

    @staticmethod
    def _find_interval(coord, grid):
        """Find the interval index such that grid[i] <= coord <= grid[i+1]."""
        for i in range(len(grid) - 1):
            if grid[i] <= coord <= grid[i + 1]:
                return i
        return -1

    @staticmethod
    def _linear_interp_1d(x, y, xi):
        """Perform 1D linear interpolation for a single point xi."""
        i = Interpolation._find_interval(xi, x)
        if i == -1:
            return None
        denominator = x[i + 1] - x[i]
        if denominator == 0:
            return y[i]
        return y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / denominator

    @staticmethod
    def _bilinear_interp_2d(x, y, z, xi, yi):
        """Perform 2D bilinear interpolation for a single point (xi, yi)."""
        i = Interpolation._find_interval(xi, x)
        j = Interpolation._find_interval(yi, y)
        if i == -1 or j == -1:
            return None

        z00 = z[i][j]
        z01 = z[i][j + 1]
        z10 = z[i + 1][j]
        z11 = z[i + 1][j + 1]

        dx0 = x[i + 1] - xi
        dx1 = xi - x[i]
        dy0 = y[j + 1] - yi
        dy1 = yi - y[j]
        dx_span = x[i + 1] - x[i]
        dy_span = y[j + 1] - y[j]

        denominator = dx_span * dy_span
        if denominator == 0:
            return z00

        return (z00 * dx0 * dy0 +
                z10 * dx1 * dy0 +
                z01 * dx0 * dy1 +
                z11 * dx1 * dy1) / denominator

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        y_interp = [
            Interpolation._linear_interp_1d(x, y, xi)
            for xi in x_interp
            if Interpolation._linear_interp_1d(x, y, xi) is not None
        ]
        return y_interp

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        z_interp = [
            Interpolation._bilinear_interp_2d(x, y, z, xi, yi)
            for xi, yi in zip(x_interp, y_interp)
            if Interpolation._bilinear_interp_2d(x, y, z, xi, yi) is not None
        ]
        return z_interp

class Interpolation:
    def __init__(self):
        pass

    @staticmethod
    def _interpolate_1d_segment(x, y, xi):
        """Calculate 1D interpolation value for a single query point xi."""
        for i in range(len(x) - 1):
            if x[i] <= xi <= x[i + 1]:
                return y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / (x[i + 1] - x[i])
        return None

    @staticmethod
    def _interpolate_2d_segment(x, y, z, xi, yi):
        """Calculate 2D bilinear interpolation value for a single query point (xi, yi)."""
        for i in range(len(x) - 1):
            if x[i] <= xi <= x[i + 1]:
                for j in range(len(y) - 1):
                    if y[j] <= yi <= y[j + 1]:
                        dx1 = x[i + 1] - xi
                        dx0 = xi - x[i]
                        dy1 = y[j + 1] - yi
                        dy0 = yi - y[j]
                        denominator = (x[i + 1] - x[i]) * (y[j + 1] - y[j])
                        return (z[i][j] * dx1 * dy1 +
                                z[i + 1][j] * dx0 * dy1 +
                                z[i][j + 1] * dx1 * dy0 +
                                z[i + 1][j + 1] * dx0 * dy0) / denominator
        return None

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """Perform 1D linear interpolation."""
        return [Interpolation._interpolate_1d_segment(x, y, xi) for xi in x_interp]

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """Perform 2D bilinear interpolation."""
        return [
            Interpolation._interpolate_2d_segment(x, y, z, xi, yi)
            for xi, yi in zip(x_interp, y_interp)
        ]

class Interpolation:
    def __init__(self):
        pass

    @staticmethod
    def _find_interval_index(x, xi):
        for i in range(len(x) - 1):
            if x[i] <= xi <= x[i + 1]:
                return i
        return None

    @staticmethod
    def _linear_interpolate(y, x, i, xi):
        return y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / (x[i + 1] - x[i])

    @staticmethod
    def _bilinear_interpolate(z, x, y, i, j, xi, yi):
        z00 = z[i][j]
        z01 = z[i][j + 1]
        z10 = z[i + 1][j]
        z11 = z[i + 1][j + 1]

        numerator = (z00 * (x[i + 1] - xi) * (y[j + 1] - yi) +
                     z10 * (xi - x[i]) * (y[j + 1] - yi) +
                     z01 * (x[i + 1] - xi) * (yi - y[j]) +
                     z11 * (xi - x[i]) * (yi - y[j]))
        denominator = (x[i + 1] - x[i]) * (y[j + 1] - y[j])
        return numerator / denominator

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        y_interp = []
        for xi in x_interp:
            i = Interpolation._find_interval_index(x, xi)
            if i is not None:
                yi = Interpolation._linear_interpolate(y, x, i, xi)
                y_interp.append(yi)
        return y_interp

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        z_interp = []
        for xi, yi in zip(x_interp, y_interp):
            i = Interpolation._find_interval_index(x, xi)
            j = Interpolation._find_interval_index(y, yi)
            if i is not None and j is not None:
                zi = Interpolation._bilinear_interpolate(z, x, y, i, j, xi, yi)
                z_interp.append(zi)
        return z_interp

class IPAddress:
    OCTET_COUNT = 4
    OCTET_MIN_VALUE = 0
    OCTET_MAX_VALUE = 255
    BINARY_OCTET_LENGTH = 8
    DOT = '.'
    EMPTY_STRING = ''

    def __init__(self, ip_address):
        self._ip_address = ip_address

    @property
    def ip_address(self):
        return self._ip_address

    @ip_address.setter
    def ip_address(self, value):
        self._ip_address = value

    def is_valid(self):
        octets = self._get_octets()
        if len(octets) != self.OCTET_COUNT:
            return False
        return all(self._is_valid_octet(octet) for octet in octets)

    def _get_octets(self):
        return self.ip_address.split(self.DOT)

    def _is_valid_octet(self, octet):
        return octet.isdigit() and self.OCTET_MIN_VALUE <= int(octet) <= self.OCTET_MAX_VALUE

    def get_octets(self):
        return self._get_octets() if self.is_valid() else []

    def get_binary(self):
        if not self.is_valid():
            return self.EMPTY_STRING
        octets = self.get_octets()
        binary_octets = [self._octet_to_binary(octet) for octet in octets]
        return self.DOT.join(binary_octets)

    def _octet_to_binary(self, octet):
        return format(int(octet), f'0{self.BINARY_OCTET_LENGTH}b')

