import numpy as np


class KappaCalculator:

    @staticmethod
    def kappa(test_data, k):
        """
        Calculate Cohen's Kappa coefficient for categorical data.

        Args:
            test_data: 2D array-like of shape (k, k) representing the confusion matrix
            k: number of categories

        Returns:
            Cohen's Kappa coefficient
        """
        data_mat = np.mat(test_data)
        observed_agreement = KappaCalculator._sum_diagonal(data_mat, k)
        expected_agreement = KappaCalculator._calculate_expected_agreement(data_mat)
        return KappaCalculator._compute_kappa(observed_agreement, expected_agreement)

    @staticmethod
    def _sum_diagonal(data_mat, k):
        """Sum the diagonal elements of the confusion matrix."""
        return np.sum(data_mat.diagonal())

    @staticmethod
    def _calculate_expected_agreement(data_mat):
        """Calculate the expected agreement probability."""
        row_sums = np.sum(data_mat, axis=1)
        col_sums = np.sum(data_mat, axis=0)
        total = np.sum(data_mat)
        if total == 0:
            return 0.0
        return float(np.dot(col_sums, row_sums) / (total * total))

    @staticmethod
    def _compute_kappa(observed_agreement, expected_agreement):
        """Compute kappa coefficient from observed and expected agreement."""
        if expected_agreement == 1:
            return 0.0
        return float((observed_agreement - expected_agreement) / (1 - expected_agreement))

    @staticmethod
    def fleiss_kappa(test_data, n_annotators, k_categories, n_samples):
        """
        Calculate Fleiss' Kappa for multi-annotator data.

        Args:
            test_data: 2D array-like of shape (N, k) where N is number of subjects 
                      and k is number of categories
            n_annotators: number of annotators per subject
            k_categories: number of categories
            n_samples: alias for n_annotators (kept for backward compatibility)

        Returns:
            Fleiss' Kappa coefficient
        """
        data_mat = np.mat(test_data, dtype=float)
        observed_agreement = KappaCalculator._calculate_fleiss_observed_agreement(
            data_mat, n_samples, k_categories
        )
        expected_agreement = KappaCalculator._calculate_fleiss_expected_agreement(
            data_mat, k_categories
        )
        return KappaCalculator._compute_kappa(observed_agreement, expected_agreement)

    @staticmethod
    def _calculate_fleiss_observed_agreement(data_mat, n_annotators, k_categories):
        """Compute observed agreement for Fleiss' Kappa."""
        total_counts = np.sum(data_mat)
        if total_counts == 0:
            return 0.0

        n_samples = n_annotators
        # Sum of squared ratings per subject, adjusted
        sum_sq_ratings = np.sum(data_mat ** 2, axis=1)
        # For each subject i: (sum_j^2 - n) / (n * (n-1))
        per_subject = (sum_sq_ratings - n_samples) / (n_samples * (n_samples - 1))
        observed = np.sum(per_subject) / len(per_subject)
        return float(observed)

    @staticmethod
    def _calculate_fleiss_expected_agreement(data_mat, k_categories):
        """Compute expected agreement for Fleiss' Kappa."""
        total_counts = np.sum(data_mat)
        if total_counts == 0:
            return 0.0
        # Marginal proportions squared and summed
        marginal_sums = np.sum(data_mat, axis=0)
        proportions = marginal_sums / total_counts
        expected = np.sum(proportions ** 2)
        return float(expected)

import numpy as np


class KappaCalculator:

    @staticmethod
    def kappa(test_data, k):
        return KappaCalculator._calculate_cohens_kappa(test_data, k)

    @staticmethod
    def _calculate_cohens_kappa(test_data, k):
        data_mat = np.mat(test_data)
        observed_agreement = KappaCalculator._calculate_observed_agreement(data_mat, k)
        expected_agreement = KappaCalculator._calculate_expected_agreement(data_mat)
        return KappaCalculator._compute_kappa(observed_agreement, expected_agreement)

    @staticmethod
    def _calculate_observed_agreement(data_mat, k):
        total = np.sum(data_mat)
        diagonal_sum = np.sum(np.diag(data_mat, 0))
        return float(diagonal_sum) / total

    @staticmethod
    def _calculate_expected_agreement(data_mat):
        total = np.sum(data_mat)
        row_sums = np.sum(data_mat, axis=1)
        col_sums = np.sum(data_mat, axis=0)
        expected = np.sum(row_sums * col_sums) / (total * total)
        return float(expected)

    @staticmethod
    def _compute_kappa(observed_agreement, expected_agreement):
        return float((observed_agreement - expected_agreement) / (1 - expected_agreement))

    @staticmethod
    def fleiss_kappa(test_data, n_items, k_categories, n_reviews):
        return KappaCalculator._calculate_fleiss_kappa(test_data, n_items, k_categories, n_reviews)

    @staticmethod
    def _calculate_fleiss_kappa(test_data, n_items, k_categories, n_reviews):
        data_mat = np.mat(test_data, dtype=float)
        observed_agreement = KappaCalculator._calculate_fleiss_observed_agreement(
            data_mat, n_items, k_categories, n_reviews
        )
        expected_agreement = KappaCalculator._calculate_fleiss_expected_agreement(
            data_mat, k_categories, n_items, n_reviews
        )
        return float(KappaCalculator._compute_kappa(observed_agreement, expected_agreement))

    @staticmethod
    def _calculate_fleiss_observed_agreement(data_mat, n_items, k_categories, n_reviews):
        total = 0.0
        p0_sum = 0.0
        for i in range(n_items):
            row_sum = np.sum(data_mat[i, :])
            total += row_sum
            squared_sum = np.sum(data_mat[i, :] ** 2)
            p0_sum += (squared_sum - n_reviews) / ((n_reviews - 1) * n_reviews)
        return p0_sum / n_items

    @staticmethod
    def _calculate_fleiss_expected_agreement(data_mat, k_categories, n_items, n_reviews):
        total = np.sum(data_mat)
        col_sums = np.sum(data_mat, axis=0)
        proportions = (col_sums / total) ** 2
        return float(np.sum(proportions))

import numpy as np


class KappaCalculator:

    @staticmethod
    def kappa(testData, k):
        dataMat = np.mat(testData)
        P0 = KappaCalculator._compute_observed_agreement_from_diagonal(dataMat, k)
        xsum = np.sum(dataMat, axis=1)
        ysum = np.sum(dataMat, axis=0)
        total_sum = np.sum(dataMat)
        Pe = float(ysum * xsum) / total_sum / total_sum
        P0 = float(P0 / total_sum)
        cohens_coefficient = float((P0 - Pe) / (1 - Pe))
        return cohens_coefficient

    @staticmethod
    def _compute_observed_agreement_from_diagonal(dataMat, k):
        P0 = 0.0
        for i in range(k):
            P0 += dataMat[i, i] * 1.0
        return P0

    @staticmethod
    def fleiss_kappa(testData, N, k, n):
        dataMat = np.mat(testData, float)
        oneMat = np.ones((k, 1))
        total_sum, P0 = KappaCalculator._compute_fleiss_agreement(dataMat, N, k, n)
        Pe = KappaCalculator._compute_expected_agreement_fleiss(dataMat, total_sum, k)
        ans = (P0 - Pe) / (1 - Pe)
        return ans[0, 0]

    @staticmethod
    def _compute_fleiss_agreement(dataMat, N, k, n):
        total_sum = 0.0
        P0 = 0.0
        for i in range(N):
            temp = KappaCalculator._compute_row_agreement(dataMat, i, k, n)
            total_sum += np.sum(dataMat[i, :])
            P0 += temp
        P0 = 1.0 * P0 / N
        return total_sum, P0

    @staticmethod
    def _compute_row_agreement(dataMat, i, k, n):
        temp = 0.0
        for j in range(k):
            temp += 1.0 * dataMat[i, j] ** 2
        temp -= n
        temp /= (n - 1) * n
        return temp

    @staticmethod
    def _compute_expected_agreement_fleiss(dataMat, total_sum, k):
        ysum = np.sum(dataMat, axis=0)
        for i in range(k):
            ysum[0, i] = (ysum[0, i] / total_sum) ** 2
        oneMat = np.ones((k, 1))
        Pe = ysum * oneMat * 1.0
        return Pe

