class NumberWordFormatter:
    HUNDRED_OFFSET = 1
    TEEN_BASE_OFFSET = 10
    TEN_INDEX_OFFSET = 1
    ZERO_GROUP = "000"
    EMPTY_STRING = ""
    ZERO_ONLY = "ZERO ONLY"
    ONLY_SUFFIX = "ONLY"
    AND_CENTS_TEMPLATE = "AND CENTS {cents} "
    HUNDRED_AND_TEMPLATE = "{hundreds} HUNDRED AND {remainder}"
    HUNDRED_TEMPLATE = "{hundreds} HUNDRED"
    GROUP_SEPARATOR = " "

    def __init__(self):
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        if x is None:
            return self.EMPTY_STRING
        return self.format_string(str(x))

    def format_string(self, x):
        left_str, right_str = self._split_decimal(x)
        left_str_rev = self._reverse_and_pad(left_str)
        groups = [''] * 5

        for i in range(len(left_str_rev) // 3):
            groups[i] = self._extract_group(left_str_rev, i)

        left_words = self._build_left_words(groups)
        cents_part = self._build_cents_part(right_str)

        if not left_words.strip():
            return self.ZERO_ONLY
        return f"{left_words.strip()} {cents_part}{self.ONLY_SUFFIX}"

    @staticmethod
    def _split_decimal(x):
        return (x.split('.') + [''])[:2]

    @staticmethod
    def _reverse_and_pad(lstr):
        lstrrev = lstr[::-1]
        remainder = len(lstrrev) % 3
        if remainder == 1:
            lstrrev += "00"
        elif remainder == 2:
            lstrrev += "0"
        return lstrrev

    @staticmethod
    def _extract_group(reversed_string, i):
        return reversed_string[3 * i:3 * i + 3][::-1]

    def _build_left_words(self, groups):
        result = self.EMPTY_STRING
        for i in range(len(groups)):
            if not groups[i]:
                continue
            group_number = int(groups[i])
            if group_number != 0:
                prefix = self.trans_three(groups[i]) + self.GROUP_SEPARATOR + self.parse_more(i) + self.GROUP_SEPARATOR
                result = prefix + result
        return result

    @staticmethod
    def _build_cents_part(rstr):
        if not rstr:
            return self.EMPTY_STRING
        return f"AND CENTS {rstr} "  # simplified; actual trans_two not used in this simplified path

    def trans_two(self, s):
        s = s.zfill(2)
        tens_digit = s[0]
        ones_digit = s[-1]
        if tens_digit == "0":
            return self.NUMBER[int(ones_digit)]
        elif tens_digit == "1":
            return self.NUMBER_TEEN[int(s) - self.TEEN_BASE_OFFSET]
        else:
            tens_word = self.NUMBER_TEN[int(tens_digit) - self.TEN_INDEX_OFFSET]
            ones_word = self.NUMBER[int(ones_digit)]
            if ones_digit == "0":
                return tens_word
            return tens_word + self.GROUP_SEPARATOR + ones_word

    def trans_three(self, s):
        hundreds_digit = s[0]
        remainder = s[1:]
        if hundreds_digit == "0":
            return self.trans_two(remainder)
        hundreds_word = self.NUMBER[int(hundreds_digit)]
        if remainder == "00":
            return self.HUNDRED_TEMPLATE.format(hundreds=hundreds_word)
        return self.HUNDRED_AND_TEMPLATE.format(hundreds=hundreds_word, remainder=self.trans_two(remainder))

    def parse_more(self, i):
        return self.NUMBER_MORE[i]

class NumberWordFormatter:
    NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
    NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                   "EIGHTEEN", "NINETEEN"]
    NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
    NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
    NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def __init__(self):
        pass

    def format(self, x):
        if x is not None:
            return self.format_string(str(x))
        else:
            return ""

    def format_string(self, x):
        lstr, rstr = (x.split('.') + [''])[:2]
        lstrrev = self._reverse_padded_integer_part(lstr)
        a = [''] * 5

        lm = self._build_left_string(lstrrev, a)

        xs = f"AND CENTS {self.trans_two(rstr)} " if rstr else ""
        if not lm.strip():
            return "ZERO ONLY"
        else:
            return f"{lm.strip()} {xs}ONLY"

    def _reverse_padded_integer_part(self, lstr):
        lstrrev = lstr[::-1]
        if len(lstrrev) % 3 == 1:
            lstrrev += "00"
        elif len(lstrrev) % 3 == 2:
            lstrrev += "0"
        return lstrrev

    def _build_left_string(self, lstrrev, a):
        lm = ""
        for i in range(len(lstrrev) // 3):
            a[i] = lstrrev[3 * i:3 * i + 3][::-1]
            if a[i] != "000":
                lm = self.trans_three(a[i]) + " " + self.parse_more(i) + " " + lm
            else:
                lm += self.trans_three(a[i])
        return lm

    def trans_two(self, s):
        s = s.zfill(2)
        if s[0] == "0":
            return self._get_number_by_index(int(s[-1]))
        elif s[0] == "1":
            return self._get_teens_by_index(int(s) - 10)
        elif s[1] == "0":
            return self._get_tens_by_index(int(s[0]) - 1)
        else:
            return self._get_tens_by_index(int(s[0]) - 1) + " " + self._get_number_by_index(int(s[-1]))

    def trans_three(self, s):
        if s[0] == "0":
            return self.trans_two(s[1:])
        elif s[1:] == "00":
            return f"{self._get_number_by_index(int(s[0]))} HUNDRED"
        else:
            return f"{self._get_number_by_index(int(s[0]))} HUNDRED AND {self.trans_two(s[1:])}"

    def parse_more(self, i):
        return self._get_numeric_more_by_index(i)

    @classmethod
    def _get_number_by_index(cls, index):
        return cls.NUMBER[index]

    @classmethod
    def _get_teens_by_index(cls, index):
        return cls.NUMBER_TEEN[index]

    @classmethod
    def _get_tens_by_index(cls, index):
        return cls.NUMBER_TEN[index]

    @classmethod
    def _get_numeric_more_by_index(cls, index):
        return cls.NUMBER_MORE[index]

class NumberWordFormatter:
    _DIGIT_GROUP_SIZE = 3
    _MAX_GROUPS = 5

    def __init__(self):
        self._number = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self._number_teen = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                             "EIGHTEEN", "NINETEEN"]
        self._number_ten = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self._number_more = ["", "THOUSAND", "MILLION", "BILLION"]
        self._number_suffix = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    @property
    def number(self):
        return self._number.copy()

    @property
    def number_teen(self):
        return self._number_teen.copy()

    @property
    def number_ten(self):
        return self._number_ten.copy()

    @property
    def number_more(self):
        return self._number_more.copy()

    @property
    def number_suffix(self):
        return self._number_suffix.copy()

    def format(self, x):
        if x is None:
            return ""
        return self.format_string(str(x))

    def format_string(self, x):
        integer_part, _, decimal_part = (x.partition('.') + [''])[:3] if '.' in x else (x, '', '')
        reversed_integer = self._pad_reversed_digits(integer_part[::-1])
        groups = self._extract_digit_groups(reversed_integer)
        integer_words = self._build_integer_words(groups)
        cents = self._format_cents(decimal_part)
        return self._assemble_result(integer_words, cents)

    def _pad_reversed_digits(self, reversed_digits):
        remainder = len(reversed_digits) % self._DIGIT_GROUP_SIZE
        if remainder == 1:
            return reversed_digits + "00"
        if remainder == 2:
            return reversed_digits + "0"
        return reversed_digits

    def _extract_digit_groups(self, reversed_digits):
        return [reversed_digits[i * self._DIGIT_GROUP_SIZE:(i + 1) * self._DIGIT_GROUP_SIZE][::-1]
                for i in range(len(reversed_digits) // self._DIGIT_GROUP_SIZE)]

    def _build_integer_words(self, groups):
        parts = []
        for i, group in enumerate(groups):
            if group != "000":
                parts.append(f"{self.trans_three(group)} {self.parse_more(i)}")
        return " ".join(parts)

    def _format_cents(self, decimal_part):
        if not decimal_part:
            return ""
        return f"AND CENTS {self.trans_two(decimal_part)}"

    def _assemble_result(self, integer_words, cents):
        if not integer_words.strip():
            return "ZERO ONLY"
        result = f"{integer_words.strip()}"
        if cents:
            result = f"{result} {cents}"
        return f"{result} ONLY"

    def trans_two(self, s):
        s = s.zfill(2)
        tens_digit = int(s[0])
        ones_digit = int(s[1])
        if tens_digit == 0:
            return self._number[ones_digit]
        if tens_digit == 1:
            return self._number_teen[ones_digit]
        if ones_digit == 0:
            return self._number_ten[tens_digit - 1]
        return f"{self._number_ten[tens_digit - 1]} {self._number[ones_digit]}"

    def trans_three(self, s):
        hundreds_digit = int(s[0])
        remaining = s[1:]
        if hundreds_digit == 0:
            return self.trans_two(remaining)
        if remaining == "00":
            return f"{self._number[hundreds_digit]} HUNDRED"
        return f"{self._number[hundreds_digit]} HUNDRED AND {self.trans_two(remaining)}"

    def parse_more(self, i):
        return self._number_more[i]

class NumericEntityUnescaper:
    HEX_BASE = 16
    DECIMAL_BASE = 10
    ESCAPE_START = '&'
    NUMERIC_START = '#'
    HEX_PREFIX_LOWER = 'x'
    HEX_PREFIX_UPPER = 'X'
    SEMICOLON = ';'

    def __init__(self):
        pass

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                if self._process_numeric_entity(string, pos, out):
                    out, pos = out[1:], pos[0]
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string, pos):
        return (string[pos] == self.ESCAPE_START and 
                pos + 1 < len(string) and 
                string[pos + 1] == self.NUMERIC_START)

    def _process_numeric_entity(self, string, pos, out):
        length = len(string)
        start = pos + 2
        is_hex = False

        if start < length:
            first_char = string[start]
            if first_char in (self.HEX_PREFIX_LOWER, self.HEX_PREFIX_UPPER):
                start += 1
                is_hex = True

        if start == length:
            return None

        end = self._find_entity_end(string, start)

        if self._is_valid_entity_termination(string, end):
            entity_value = self._parse_entity_value(string, start, end, is_hex)
            if entity_value is not None:
                out.append(entity_value)
                return (chr(entity_value), end + 1)

        return None

    def _find_entity_end(self, string, start):
        end = start
        length = len(string)
        while end < length and self.is_hex_char(string[end]):
            end += 1
        return end

    def _is_valid_entity_termination(self, string, end):
        return end < len(string) and string[end] == self.SEMICOLON

    def _parse_entity_value(self, string, start, end, is_hex):
        base = self.HEX_BASE if is_hex else self.DECIMAL_BASE
        try:
            return int(string[start:end], base)
        except Exception:
            return None

    @staticmethod
    def is_hex_char(char):
        return char.isdigit() or ('a' <= char.lower() <= 'f')

class NumericEntityUnescaper:
