class NumericEntityUnescaper:
    HEX_BASE = 16
    DECIMAL_BASE = 10

    def __init__(self):
        self._hex_chars = set('0123456789abcdefABCDEF')

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                escaped_char, new_pos = self._decode_numeric_entity(string, pos, length)
                if escaped_char is not None:
                    out.append(escaped_char)
                    pos = new_pos
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string, pos):
        return pos + 2 < len(string) and string[pos] == '&' and string[pos + 1] == '#'

    def _decode_numeric_entity(self, string, pos, length):
        start = pos + 2
        is_hex = False

        if start < length and string[start] in ('x', 'X'):
            start += 1
            is_hex = True

        if start >= length:
            return None, pos

        end = start
        while end < length and self._is_hex_char(string[end], is_hex):
            end += 1

        if end < length and string[end] == ';':
            entity_str = string[start:end]
            if self._is_valid_entity_string(entity_str, is_hex):
                try:
                    entity_value = int(entity_str, self._get_base(is_hex))
                    return chr(entity_value), end + 1
                except ValueError:
                    return None, pos

        return None, pos

    def _is_hex_char(self, char, is_hex):
        if is_hex:
            return char in self._hex_chars
        return char.isdigit()

    def _is_valid_entity_string(self, entity_str, is_hex):
        if not entity_str:
            return False
        if is_hex:
            return all(c in self._hex_chars for c in entity_str)
        return entity_str.isdigit()

    @staticmethod
    def _get_base(is_hex):
        return 16 if is_hex else 10

    @staticmethod
    def is_hex_char(char):
        return char.isdigit() or ('a' <= char.lower() <= 'f')

class NumericEntityUnescaper:
    HEX_BASE = 16
    DECIMAL_BASE = 10
    AMPERSAND = '&'
    HASH = '#'
    HEX_X_LOWER = 'x'
    HEX_X_UPPER = 'X'
    SEMICOLON = ';'

    def __init__(self):
        pass

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - self.TWO():
            if self.is_numeric_entity_start(string, pos):
                result = self.process_numeric_entity(string, pos)
                if result is not None:
                    out.append(result[0])
                    pos = result[1]
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def TWO(self):
        return 2

    def is_numeric_entity_start(self, string, pos):
        return string[pos] == self.AMPERSAND and string[pos + 1] == self.HASH

    def process_numeric_entity(self, string, pos):
        start = pos + self.TWO()
        is_hex = False
        first_char = string[start]

        if first_char == self.HEX_X_LOWER or first_char == self.HEX_X_UPPER:
            start += 1
            is_hex = True

        length = len(string)

        if start == length:
            return None

        end = self.find_hex_end(string, start)

        if end < length and string[end] == self.SEMICOLON:
            entity_value = self.try_parse_entity_value(string, start, end, is_hex)
            if entity_value is not None:
                return (chr(entity_value), end + 1)

        return None

    def find_hex_end(self, string, start):
        end = start
        length = len(string)
        while end < length and self.is_hex_char(string[end]):
            end += 1
        return end

    def try_parse_entity_value(self, string, start, end, is_hex):
        try:
            base = self.HEX_BASE if is_hex else self.DECIMAL_BASE
            return int(string[start:end], base)
        except ValueError:
            return None

    @staticmethod
    def is_hex_char(char):
        return char.isdigit() or ('a' <= char.lower() <= 'f')

class NumericEntityUnescaper:
    HEX_RADIX = 16
    DECIMAL_RADIX = 10
    AMPERсанд = '&'
    HASH = '#'
    HEX_PREFIX_LOWER = 'x'
    HEX_PREFIX_UPPER = 'X'
    SEMICOLON = ';'

    def __init__(self):
        pass

    def replace(self, string: str) -> str:
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                entity_result = self._parse_numeric_entity(string, pos, length)
                if entity_result is not None:
                    out.append(entity_result['char'])
                    pos = entity_result['next_pos']
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string: str, pos: int) -> bool:
        return (pos + 1 < len(string) and
                string[pos] == self.AMBERсанд and
                string[pos + 1] == self.HASH)

    def _parse_numeric_entity(self, string: str, pos: int, length: int) -> dict:
        start = pos + 2
        is_hex = False
        first_char = string[start]

        if first_char in (self.HEX_PREFIX_LOWER, self.HEX_PREFIX_UPPER):
            start += 1
            is_hex = True

        if start == length:
            return None

        end = self._find_entity_end(string, start, length)

        if end < length and string[end] == self.SEMICOLON:
            try:
                entity_value = int(string[start:end], self.HEX_RADIX if is_hex else self.DECIMAL_RADIX)
            except ValueError:
                return None

            return {'char': chr(entity_value), 'next_pos': end + 1}

        return None

    def _find_entity_end(self, string: str, start: int, length: int) -> int:
        end = start
        while end < length and self.is_hex_char(string[end]):
            end += 1
        return end

    @staticmethod
    def is_hex_char(char: str) -> bool:
