class RPGCharacter:
    MAX_HP = 100
    HEAL_AMOUNT = 10
    MAX_LEVEL = 100
    HP_PER_LEVEL = 20
    ATTACK_PER_LEVEL = 5
    DEFENSE_PER_LEVEL = 5
    EXP_PER_LEVEL = 100

    def __init__(self, name, hp, attack_power, defense, level=1):
        self._name = name
        self.hp = hp
        self.attack_power = attack_power
        self.defense = defense
        self.level = level
        self.exp = 0

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        self._name = value

    def attack(self, other_character):
        damage = self._calculate_damage(other_character.defense)
        other_character.hp -= damage

    def _calculate_damage(self, other_defense):
        return max(self.attack_power - other_defense, 1)

    def heal(self):
        self.hp = min(self.hp + self.HEAL_AMOUNT, self.MAX_HP)
        return self.hp

    def gain_exp(self, amount):
        amount = self._add_experience(amount)

    def _add_experience(self, amount):
        while amount != 0:
            exp_to_level_up = self.level * self.EXP_PER_LEVEL - self.exp
            if amount >= exp_to_level_up:
                amount -= exp_to_level_up
                self.level_up()
            else:
                self.exp += amount
                amount = 0
        return amount

    def level_up(self):
        if self.level < self.MAX_LEVEL:
            self.level += 1
            self.exp = 0
            self.hp += self.HP_PER_LEVEL
            self.attack_power += self.ATTACK_PER_LEVEL
            self.defense += self.DEFENSE_PER_LEVEL
        return self.level, self.hp, self.attack_power, self.defense

    def is_alive(self):
        return self.hp > 0

class RPGCharacter:
    MAX_HP = 100
    MAX_LEVEL = 100
    LEVEL_UP_HP_INCREMENT = 20
    LEVEL_UP_ATTACK_INCREMENT = 5
    LEVEL_UP_DEFENSE_INCREMENT = 5
    HEAL_AMOUNT = 10
    EXP_PER_LEVEL_BASE = 100

    def __init__(self, name, hp, attack_power, defense, level=1):
        self.name = name
        self.hp = hp
        self.attack_power = attack_power
        self.defense = defense
        self.level = level
        self.exp = 0

    def attack(self, other_character):
        damage = self.calculate_damage(other_character)
        other_character.receive_damage(damage)

    def calculate_damage(self, other_character):
        return max(self.attack_power - other_character.defense, 1)

    def heal(self):
        self.hp = min(self.hp + self.HEAL_AMOUNT, self.MAX_HP)
        return self.hp

    def gain_exp(self, amount):
        while amount != 0:
            exp_to_next_level = self.calc_exp_to_next_level() - self.exp
            if exp_to_next_level <= amount:
                amount -= exp_to_next_level
                self.level_up()
            else:
                self.exp += amount
                amount = 0

    def calc_exp_to_next_level(self):
        return self.level * self.EXP_PER_LEVEL_BASE

    def level_up(self):
        if self.level < self.MAX_LEVEL:
            self.level += 1
            self.exp = 0
            self.apply_level_up_stat_increments()
        return self.level, self.hp, self.attack_power, self.defense

    def apply_level_up_stat_increments(self):
        self.hp += self.LEVEL_UP_HP_INCREMENT
        self.attack_power += self.LEVEL_UP_ATTACK_INCREMENT
        self.defense += self.LEVEL_UP_DEFENSE_INCREMENT

    def is_alive(self):
        return self.hp > 0

class RPGCharacter:
    MAX_LEVEL = 100
    MAX_HP = 100
    HEAL_AMOUNT = 10
    EXP_PER_LEVEL = 100
    LEVEL_UP_HP_BONUS = 20
    LEVEL_UP_ATTACK_BONUS = 5
    LEVEL_UP_DEFENSE_BONUS = 5
    MIN_DAMAGE = 1

    def __init__(self, name, hp, attack_power, defense, level=1):
        self.name = name
        self.hp = hp
        self.attack_power = attack_power
        self.defense = defense
        self.level = level
        self.exp = 0

    def attack(self, other_character):
        damage = self.calculate_damage(other_character)
        other_character.hp -= damage

    def calculate_damage(self, other_character):
        return max(self.attack_power - other_character.defense, self.MIN_DAMAGE)

    def heal(self):
        self.hp += self.HEAL_AMOUNT
        if self.hp > self.MAX_HP:
            self.hp = self.MAX_HP
        return self.hp

    def gain_exp(self, amount):
        remaining_exp = amount
        while remaining_exp > 0:
            exp_to_next_level = self.get_exp_to_next_level()
            if remaining_exp >= exp_to_next_level:
                remaining_exp -= exp_to_next_level
                self.level_up()
            else:
                self.exp += remaining_exp
                remaining_exp = 0

    def get_exp_to_next_level(self):
        return self.level * self.EXP_PER_LEVEL - self.exp

    def level_up(self):
        if self.level < self.MAX_LEVEL:
            self.level += 1
            self.exp = 0
            self.apply_level_up_bonuses()
        return self.level, self.hp, self.attack_power, self.defense

    def apply_level_up_bonuses(self):
        self.hp += self.LEVEL_UP_HP_BONUS
        self.attack_power += self.LEVEL_UP_ATTACK_BONUS
        self.defense += self.LEVEL_UP_DEFENSE_BONUS

    def is_alive(self):
        return self.hp > 0

class RPGCharacter:
    MAX_HP = 100
    HEAL_AMOUNT = 10
    MAX_LEVEL = 100
    LEVEL_UP_HP_GAIN = 20
    LEVEL_UP_ATTACK_GAIN = 5
    LEVEL_UP_DEFENSE_GAIN = 5
    XP_PER_LEVEL = 100

    def __init__(self, name, hp, attack_power, defense, level=1):
        self._name = name
        self._hp = hp
        self._attack_power = attack_power
        self._defense = defense
        self._level = level
        self._exp = 0

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        self._name = value

    @property
    def hp(self):
        return self._hp

    @hp.setter
    def hp(self, value):
        self._hp = value

    @property
    def attack_power(self):
        return self._attack_power

    @attack_power.setter
    def attack_power(self, value):
        self._attack_power = value

    @property
    def defense(self):
        return self._defense

    @defense.setter
    def defense(self, value):
        self._defense = value

    @property
    def level(self):
        return self._level

    @level.setter
    def level(self, value):
        self._level = value

    @property
    def exp(self):
        return self._exp

    @exp.setter
    def exp(self, value):
        self._exp = value

    def attack(self, other_character):
        damage = self._calculate_damage(other_character)
        other_character.hp -= damage

    def _calculate_damage(self, other_character):
        return max(self._attack_power - other_character.defense, 1)

    def heal(self):
        self.hp = min(self.hp + self.HEAL_AMOUNT, self.MAX_HP)
        return self.hp

    def gain_exp(self, amount):
        while amount != 0:
            if self._should_level_up(self.exp, self.level, amount):
                xp_to_consume = self._level_up_xp_required(self.level, self.exp)
                amount -= xp_to_consume
                self.level_up()
            else:
                self.exp += amount
                amount = 0

    def _should_level_up(self, current_exp, current_level, additional_exp):
        return current_exp + additional_exp >= current_level * self.XP_PER_LEVEL

    def _level_up_xp_required(self, current_level, current_exp):
        return current_level * self.XP_PER_LEVEL - current_exp

    def level_up(self):
        if self.level < self.MAX_LEVEL:
            self.level += 1
            self.exp = 0
            self.hp = self.hp + self.LEVEL_UP_HP_GAIN
            self.attack_power = self.attack_power + self.LEVEL_UP_ATTACK_GAIN
            self.defense = self.defense + self.LEVEL_UP_DEFENSE_GAIN
        return self.level, self.hp, self.attack_power, self.defense

    def is_alive(self):
        return self.hp > 0

