        # Encapsulate Collection: return a copy to prevent external modification
        return self._white_list.copy()

    @property
    def send_struct(self):
        return self._send_struct

    @property
    def receive_struct(self):
        return self._receive_struct

    def _is_valid_info(self, info):
        # Extract Method from recv and send
        return isinstance(info, dict) and "addr" in info and "content" in info

    def add_white_list(self, addr):
        if addr in self._white_list:
            return False
        self._white_list.append(addr)
        return self.white_list

    def del_white_list(self, addr):
        if addr not in self._white_list:
            return False
        self._white_list.remove(addr)
        return self.white_list

    def recv(self, info):
        # Decompose Conditional / Extract Method logic used in guard
        if not self._is_valid_info(info):
            return self.INVALID_RECV_CODE

        addr = info["addr"]
        content = info["content"]

        # Replace Nested Conditional with Guard Clauses
        if addr not in self._white_list:
            return False

        self._receive_struct = {"addr": addr, "content": content}
        return self._receive_struct["content"]

    def send(self, info):
        if not self._is_valid_info(info):
            return "info structure is not correct"

        # Inline Temp / Direct assignment
        self._send_struct = {"addr": info["addr"], "content": info["content"]}

    def show(self, type):
        # Consolidate Duplicate Conditional Fragments / Simplify logic
        if type == "send":
            return self.send_struct
        if type == "receive":
            return self.receive_struct
        return False

