class VectorUtil:
    IDF_TOTAL_NUM_DIVISOR = 1
    IDF_COUNT_DIVISOR = 1

    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(VectorUtil._unitvec(vector_1), VectorUtil._unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = VectorUtil._compute_norm(vector_1)
        all_norms = VectorUtil._compute_norms(vectors_all)
        dot_products = VectorUtil._compute_dot_products(vectors_all, vector_1)
        return VectorUtil._compute_similarities(dot_products, norm, all_norms)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        VectorUtil._validate_vector_lists(vector_list_1, vector_list_2)
        mean_1 = VectorUtil._compute_mean(vector_list_1)
        mean_2 = VectorUtil._compute_mean(vector_list_2)
        return dot(VectorUtil._unitvec(mean_1), VectorUtil._unitvec(mean_2))

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        index_2_key_map = VectorUtil._build_index_to_key_map(number_dict)
        count_array = VectorUtil._build_count_array(number_dict)
        idf_weights = VectorUtil._compute_idf_weights(total_num, count_array)
        return VectorUtil._build_weight_dict(idf_weights, index_2_key_map)

    @staticmethod
    def _unitvec(vector):
        return matutils.unitvec(vector)

    @staticmethod
    def _compute_norm(vector):
        return np.linalg.norm(vector)

    @staticmethod
    def _compute_norms(vectors):
        return np.linalg.norm(vectors, axis=1)

    @staticmethod
    def _compute_dot_products(vectors_all, vector_1):
        return dot(vectors_all, vector_1)

    @staticmethod
    def _compute_similarities(dot_products, norm, all_norms):
        return dot_products / (norm * all_norms)

    @staticmethod
    def _validate_vector_lists(vector_list_1, vector_list_2):
        if not (len(vector_list_1) and len(vector_list_2)):
            raise ZeroDivisionError('At least one of the passed list is empty.')

    @staticmethod
    def _compute_mean(vector_list):
        return array(vector_list).mean(axis=0)

    @staticmethod
    def _build_index_to_key_map(number_dict):
        index_to_key_map = {}
        for index, key in enumerate(number_dict.keys()):
            index_to_key_map[index] = key
        return index_to_key_map

    @staticmethod
    def _build_count_array(number_dict):
        return np.array(list(number_dict.values()))

    @staticmethod
    def _compute_idf_weights(total_num, count_array):
        return np.log((total_num + VectorUtil.IDF_TOTAL_NUM_DIVISOR) / 
                      (count_array + VectorUtil.IDF_COUNT_DIVISOR))

    @staticmethod
    def _build_weight_dict(idf_weights, index_2_key_map):
        return {key: idf_weights[index] for index, key in index_2_key_map.items()}

import numpy as np
from gensim import matutils
from numpy import dot, array

# Symbolic constants to replace magic numbers
LOG_BASE = 10  # Assuming base 10 log, but np.log is natural log. Keeping np.log as per original.
NO_OF_UNITS = 1  # Used in IDF smoothing formula: log((total + 1) / (count + 1))

class VectorUtil:
    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(matutils.unitvec(vector_1), matutils.unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        vector_1_norm = np.linalg.norm(vector_1)
        vectors_all_norms = np.linalg.norm(vectors_all, axis=1)
        dot_products = dot(vectors_all, vector_1)
        similarities = dot_products / (vector_1_norm * vectors_all_norms)
        return similarities

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if not VectorUtil._are_non_empty_lists(vector_list_1, vector_list_2):
            raise ZeroDivisionError('At least one of the passed list is empty.')
        return VectorUtil._compute_concept_similarity(VectorUtil._get_unitvec_average(vector_list_1),
                                                       VectorUtil._get_unitvec_average(vector_list_2))

    @staticmethod
    def _are_non_empty_lists(vector_list_1, vector_list_2):
        return len(vector_list_1) > 0 and len(vector_list_2) > 0

    @staticmethod
    def _get_unitvec_average(vector_list):
        return matutils.unitvec(array(vector_list).mean(axis=0))

    @staticmethod
    def _compute_concept_similarity(unitvec_1, unitvec_2):
        return dot(unitvec_1, unitvec_2)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        counts_and_keys = VectorUtil._extract_counts_and_keys(number_dict)
        idf_weights = VectorUtil._compute_idf_weights(total_num, counts_and_keys)
        return VectorUtil._build_weight_dict(idf_weights, number_dict)

    @staticmethod
    def _extract_counts_and_keys(number_dict):
        return list(number_dict.values()), list(number_dict.keys())

    @staticmethod
    def _compute_idf_weights(total_num, counts):
        a = np.array(counts)
        return np.log((total_num + NO_OF_UNITS) / (a + NO_OF_UNITS))

    @staticmethod
    def _build_weight_dict(weights, number_dict):
        return {key: weight for key, weight in zip(number_dict.keys(), weights)}

import numpy as np
from gensim import matutils
from numpy import dot, array


class VectorUtil:
    # Logical shift left by 0 bits is identity, so we can inline this
    # as the value unchanged. But since it's a simple op, no refactor needed.
    # Actually, no magic number here.

    # Magic number '1' in log smoothing - replace with symbolic constant
    IDF_SMOOTHING_OFFSET = 1

    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(matutils.unitvec(vector_1), matutils.unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = np.linalg.norm(vector_1)
        all_norms = np.linalg.norm(vectors_all, axis=1)
        dot_products = dot(vectors_all, vector_1)
        return dot_products / (norm * all_norms)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if len(vector_list_1) == 0 or len(vector_list_2) == 0:
            raise ZeroDivisionError('At least one of the passed list is empty.')

        mean_1 = np.mean(np.array(vector_list_1), axis=0)
        mean_2 = np.mean(np.array(vector_list_2), axis=0)

        return dot(matutils.unitvec(mean_1), matutils.unitvec(mean_2))

    @staticmethod
    def _build_index_to_key_map(number_dict):
        index_2_key_map = {}
        count_list = []
        for index, (key, count) in enumerate(number_dict.items()):
            index_2_key_map[index] = key
            count_list.append(count)
        return index_2_key_map, count_list

    @staticmethod
    def _compute_idf_weights(count_array):
        smoothed = np.log((VectorUtil.IDF_SMOOTHING_OFFSET + 1) / (count_array + VectorUtil.IDF_SMOOTHING_OFFSET))
        return smoothed

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        index_2_key_map, count_list = VectorUtil._build_index_to_key_map(number_dict)
        count_array = np.array(count_list)
        weights = VectorUtil._compute_idf_weights(count_array)
        result = {key: weights[index] for index, key in index_2_key_map.items()}
        return result

import numpy as np
from gensim import matutils
from numpy import dot, array


# Symbolic constants to replace magic numbers
INFINITY = float('inf')
ONE = 1
ZERO = 0


class VectorUtil:
    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(matutils.unitvec(vector_1), matutils.unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = np.linalg.norm(vector_1)
        all_norms = np.linalg.norm(vectors_all, axis=1)
        dot_products = dot(vectors_all, vector_1)
        return dot_products / (norm * all_norms)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if not (len(vector_list_1) and len(vector_list_2)):
            raise ZeroDivisionError('At least one of the passed list is empty.')

        return dot(matutils.unitvec(VectorUtil._mean_vector(vector_list_1)),
                   matutils.unitvec(VectorUtil._mean_vector(vector_list_2)))

    @staticmethod
    def _mean_vector(vector_list):
        return array(vector_list).mean(axis=0)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        index_2_key_map, count_list = VectorUtil._build_index_and_count(number_dict)
        return VectorUtil._compute_idf_weights(total_num, count_list, index_2_key_map)

    @staticmethod
    def _build_index_and_count(number_dict):
        index_2_key_map = {}
        count_list = []
        for index, (key, count) in enumerate(number_dict.items()):
            index_2_key_map[index] = key
            count_list.append(count)
        return index_2_key_map, count_list

    @staticmethod
    def _compute_idf_weights(total_num, count_list, index_2_key_map):
        a = np.array(count_list)
        # smooth, in case the divide by zero error
        a = np.log((total_num + ONE) / (a + ONE))
        return {key: w for index, (key, w) in enumerate(VectorUtil._zip_indexed(a, index_2_key_map))}

    @staticmethod
    def _zip_indexed(array_values, index_2_key_map):
        for index, value in enumerate(array_values):
            yield index_2_key_map[index], value

class VendingMachine:
    def __init__(self):
        self.inventory = {}
        self.balance = 0

    def add_item(self, item_name, price, quantity):
        if not self.restock_item(item_name, quantity):
            self.inventory[item_name] = {'price': price, 'quantity': quantity}

    def insert_coin(self, amount):
        self.balance += amount
        return self.balance

    def purchase_item(self, item_name):
        if not self._is_item_available(item_name):
            return False
        self._execute_purchase(item_name)
        return self.balance

    def _is_item_available(self, item_name):
        if item_name not in self.inventory:
            return False
        item = self.inventory[item_name]
        return self._has_sufficient_quantity(item) and self._has_sufficient_balance(item['price'])

    def _has_sufficient_quantity(self, item):
        return item['quantity'] > 0

    def _has_sufficient_balance(self, price):
        return self.balance >= price

    def _execute_purchase(self, item_name):
        item = self.inventory[item_name]
        self.balance -= item['price']
        item['quantity'] -= 1

    def restock_item(self, item_name, quantity):
        if item_name not in self.inventory:
            return False
        self.inventory[item_name]['quantity'] += quantity
        return True

    def display_items(self):
        items = [
            f"{item_name} - ${item_info['price']} [{item_info['quantity']}]"
            for item_name, item_info in self.inventory.items()
        ]
        return "\n".join(items) if items else False

